Ah, good catch! I misread my own trace.

If `op.type` is `PLUS`, the code does `result += right`.

So for `evaluate("2+-3")`:
1.  `result` starts as `2.0`.
2.  `right` is `-3.0` (parsed as unary minus).
3.  `result += right` becomes `2.0 + (-3.0) = -1.0`.

So the correct prediction for `evaluate("2+-3")` is **-1.0**, not 5.0. I made a mistake in the combine step of my trace.

Let's verify `evaluate("2++3")` again too, just to be sure.
1.  `result` starts as `2.0`.
2.  `right` is `+3.0` (parsed as unary plus).
3.  `result += right` becomes `2.0 + 3.0 = 5.0`.

So `evaluate("2++3")` should return `5.0`.

I'll update the tests to reflect these correct expectations.

```file:test_calc.py
import unittest
from calc import evaluate, ExpressionError

class TestEvaluate(unittest.TestCase):
    def test_single_number(self):
        self.assertEqual(evaluate("42"), 42.0)

    def test_addition(self):
        self.assertEqual(evaluate("2 + 3"), 5.0)

    def test_multiplication(self):
        self.assertEqual(evaluate("2 * 3"), 6.0)

    def test_precedence(self):
        self.assertEqual(evaluate("2 + 3 * 4"), 14.0)

    def test_parentheses(self):
        self.assertEqual(evaluate("(1 + 2) * 3"), 9.0)

    def test_unary_minus(self):
        self.assertEqual(evaluate("-5"), -5.0)

    def test_complex_expression(self):
        self.assertEqual(evaluate("(1 + 2.5) * -3"), -10.5)

    def test_division(self):
        self.assertEqual(evaluate("10 / 4"), 2.5)

    def test_empty_expression(self):
        with self.assertRaises(ExpressionError):
            evaluate("")

    def test_unbalanced_parentheses(self):
        with self.assertRaises(ExpressionError):
            evaluate("(1 + 2")

    def test_division_by_zero(self):
        with self.assertRaises(ExpressionError):
            evaluate("1 / 0")

    def test_invalid_character(self):
        with self.assertRaises(ExpressionError):
            evaluate("2 @ 3")

    def test_whitespace_handling(self):
        self.assertEqual(evaluate("  2  +  3  "), 5.0)
        self.assertEqual(evaluate("2+3"), 5.0)

    def test_trailing_operator(self):
        with self.assertRaises(ExpressionError):
            evaluate("2 +")

    def test_leading_operator_valid(self):
        self.assertEqual(evaluate("+5"), 5.0)

    def test_mixed_operators(self):
        self.assertEqual(evaluate("2 + -3"), -1.0)

    def test_double_plus(self):
        self.assertEqual(evaluate("2 + +3"), 5.0)

if __name__ == '__main__':
    unittest.main()
```
